values
  ('84bc4a86-edd4-4b13-8386-5a91b29e4b65', 'b2c3d4e5-6f7a-4c22-9d12-2e3f4a5b6c22', null, 'topic'::public.curated_course_node_type, 'Anthropology, the Culture Concept, and Holistic Human Inquiry', 'This unit introduces anthropology as a way of asking what it means to be human across time, place, biology, language, culture, and power. Students learn that culture is useful, contested, and never static.', 0),
  ('37bb2379-3c82-4106-be91-312a8e7517a4', 'b2c3d4e5-6f7a-4c22-9d12-2e3f4a5b6c22', '84bc4a86-edd4-4b13-8386-5a91b29e4b65', 'subtopic'::public.curated_course_node_type, 'Anthropology''s Holistic Frame', 'Students learn why anthropology connects cultural, biological, archaeological, and linguistic evidence instead of isolating social life from bodies, histories, and environments.', 0),
  ('13de2b02-328d-4053-b92b-2c4c1d31ad00', 'b2c3d4e5-6f7a-4c22-9d12-2e3f4a5b6c22', '37bb2379-3c82-4106-be91-312a8e7517a4', 'concept'::public.curated_course_node_type, 'Four-field anthropology', null, 0),
  ('9aabfc68-3c4e-4f9c-9338-58b35b46ccdf', 'b2c3d4e5-6f7a-4c22-9d12-2e3f4a5b6c22', '37bb2379-3c82-4106-be91-312a8e7517a4', 'concept'::public.curated_course_node_type, 'Comparison and relativism', null, 1),
  ('de32f5f6-e3fd-4fdf-a28b-6986ebcb01f9', 'b2c3d4e5-6f7a-4c22-9d12-2e3f4a5b6c22', '37bb2379-3c82-4106-be91-312a8e7517a4', 'concept'::public.curated_course_node_type, 'Human variation and commonality', null, 2),
  ('92861f93-f994-4c49-9178-e78cd152ca66', 'b2c3d4e5-6f7a-4c22-9d12-2e3f4a5b6c22', '37bb2379-3c82-4106-be91-312a8e7517a4', 'concept'::public.curated_course_node_type, 'Anthropology as field-based inquiry', null, 3),
  ('8e5c91a9-dc0a-4b3c-8c25-c66f26afc57d', 'b2c3d4e5-6f7a-4c22-9d12-2e3f4a5b6c22', '84bc4a86-edd4-4b13-8386-5a91b29e4b65', 'subtopic'::public.curated_course_node_type, 'The Culture Concept', 'The point is to understand culture as learned, shared, contested, embodied, and historically produced.', 1),
  ('5c365959-d5c7-4db0-a61b-e3f14c61a670', 'b2c3d4e5-6f7a-4c22-9d12-2e3f4a5b6c22', '8e5c91a9-dc0a-4b3c-8c25-c66f26afc57d', 'concept'::public.curated_course_node_type, 'Culture as meaning and practice', null, 0),
  ('9dd447a0-ec4f-4400-9064-2955ca86e6c0', 'b2c3d4e5-6f7a-4c22-9d12-2e3f4a5b6c22', '8e5c91a9-dc0a-4b3c-8c25-c66f26afc57d', 'concept'::public.curated_course_node_type, 'Norms, values, symbols, and institutions', null, 1),
  ('6ad2b0f9-ed72-4b5c-abfb-5608873810a7', 'b2c3d4e5-6f7a-4c22-9d12-2e3f4a5b6c22', '8e5c91a9-dc0a-4b3c-8c25-c66f26afc57d', 'concept'::public.curated_course_node_type, 'Culture as process rather than container', null, 2),
  ('6e009b37-3284-461c-8167-bb5d4c15ef36', 'b2c3d4e5-6f7a-4c22-9d12-2e3f4a5b6c22', '8e5c91a9-dc0a-4b3c-8c25-c66f26afc57d', 'concept'::public.curated_course_node_type, 'Critiques of bounded culture models', null, 3),
  ('381c03aa-d135-400b-a42c-d728088b0c7b', 'b2c3d4e5-6f7a-4c22-9d12-2e3f4a5b6c22', '84bc4a86-edd4-4b13-8386-5a91b29e4b65', 'subtopic'::public.curated_course_node_type, 'Ethnocentrism and Cultural Relativism', 'Students learn to suspend easy judgment while still making ethical and analytical distinctions.', 2),
  ('86483ed0-71ea-4477-a1bc-1701b4e67032', 'b2c3d4e5-6f7a-4c22-9d12-2e3f4a5b6c22', '381c03aa-d135-400b-a42c-d728088b0c7b', 'concept'::public.curated_course_node_type, 'Ethnocentrism', null, 0),
  ('f2912278-2363-466e-b443-c58dacb198bf', 'b2c3d4e5-6f7a-4c22-9d12-2e3f4a5b6c22', '381c03aa-d135-400b-a42c-d728088b0c7b', 'concept'::public.curated_course_node_type, 'Methodological relativism', null, 1),
  ('5bac3310-af92-4a5f-84a3-c8f88a5008e1', 'b2c3d4e5-6f7a-4c22-9d12-2e3f4a5b6c22', '381c03aa-d135-400b-a42c-d728088b0c7b', 'concept'::public.curated_course_node_type, 'Moral relativism debates', null, 2),
  ('ec53eb40-644d-44dd-b71c-2cb65360100f', 'b2c3d4e5-6f7a-4c22-9d12-2e3f4a5b6c22', '381c03aa-d135-400b-a42c-d728088b0c7b', 'concept'::public.curated_course_node_type, 'Comparison without hierarchy', null, 3),
  ('d028ace4-e0ba-4dfe-8ee6-2e465a5bd0c2', 'b2c3d4e5-6f7a-4c22-9d12-2e3f4a5b6c22', null, 'topic'::public.curated_course_node_type, 'Ethnography, Participant Observation, and Fieldwork as Method', 'Ethnography is the signature method of cultural anthropology. Students learn how long-term attention, participation, listening, and writing turn everyday life into evidence.', 1),
  ('9e8be171-1177-4da3-b23c-fd14f1c353d9', 'b2c3d4e5-6f7a-4c22-9d12-2e3f4a5b6c22', 'd028ace4-e0ba-4dfe-8ee6-2e465a5bd0c2', 'subtopic'::public.curated_course_node_type, 'Participant Observation', 'Students learn why anthropologists study with people rather than only about people.', 0),
  ('53cac185-a7d8-40ad-bf20-b82f4163ffdf', 'b2c3d4e5-6f7a-4c22-9d12-2e3f4a5b6c22', '9e8be171-1177-4da3-b23c-fd14f1c353d9', 'concept'::public.curated_course_node_type, 'Participation and observation', null, 0),
  ('2cb59cfb-9c06-4e79-9514-ae98901e5874', 'b2c3d4e5-6f7a-4c22-9d12-2e3f4a5b6c22', '9e8be171-1177-4da3-b23c-fd14f1c353d9', 'concept'::public.curated_course_node_type, 'Rapport and field relationships', null, 1),
  ('00821d28-60ab-4c40-885d-cb50982699be', 'b2c3d4e5-6f7a-4c22-9d12-2e3f4a5b6c22', '9e8be171-1177-4da3-b23c-fd14f1c353d9', 'concept'::public.curated_course_node_type, 'Everyday life as evidence', null, 2),
  ('2d710f44-afe1-4bc8-afaf-e0e346977982', 'b2c3d4e5-6f7a-4c22-9d12-2e3f4a5b6c22', '9e8be171-1177-4da3-b23c-fd14f1c353d9', 'concept'::public.curated_course_node_type, 'Fieldsite boundaries and multi-sited research', null, 3),
  ('8ce4d366-1637-4385-ad2d-a895052bedef', 'b2c3d4e5-6f7a-4c22-9d12-2e3f4a5b6c22', 'd028ace4-e0ba-4dfe-8ee6-2e465a5bd0c2', 'subtopic'::public.curated_course_node_type, 'Interviews and Fieldnotes', 'The gist is learning how questions, listening, recording, and writing shape the evidence produced.', 1),
  ('be599eab-9ca7-47ed-b330-dad48d326f23', 'b2c3d4e5-6f7a-4c22-9d12-2e3f4a5b6c22', '8ce4d366-1637-4385-ad2d-a895052bedef', 'concept'::public.curated_course_node_type, 'Open-ended interviews', null, 0),
