  ('dceb4186-2f31-4e30-9800-9bcc594fd89c', 'b2c3d4e5-6f7a-4c22-9d12-2e3f4a5b6c22', '8ce4d366-1637-4385-ad2d-a895052bedef', 'concept'::public.curated_course_node_type, 'Jottings and expanded fieldnotes', null, 2),
