  ('08c1a9d8-6643-4dee-b5b4-33c6fa3ddf21', 'b2c3d4e5-6f7a-4c22-9d12-2e3f4a5b6c22', 'd028ace4-e0ba-4dfe-8ee6-2e465a5bd0c2', 'subtopic'::public.curated_course_node_type, 'Ethnographic Analysis', 'Students learn how field materials become concepts, arguments, and written accounts.', 2),
  ('b0d5259d-e2da-4d3a-9376-a93b9a2cb078', 'b2c3d4e5-6f7a-4c22-9d12-2e3f4a5b6c22', '08c1a9d8-6643-4dee-b5b4-33c6fa3ddf21', 'concept'::public.curated_course_node_type, 'Coding and memoing', null, 0),
  ('91ec9a69-b4d6-4493-b5cf-8ab3cfa8ad7d', 'b2c3d4e5-6f7a-4c22-9d12-2e3f4a5b6c22', '08c1a9d8-6643-4dee-b5b4-33c6fa3ddf21', 'concept'::public.curated_course_node_type, 'Emic and etic perspectives', null, 1),
  ('ec5a9d72-a219-4064-81db-6ca02ad46342', 'b2c3d4e5-6f7a-4c22-9d12-2e3f4a5b6c22', '08c1a9d8-6643-4dee-b5b4-33c6fa3ddf21', 'concept'::public.curated_course_node_type, 'Pattern, contradiction, and case', null, 2),
  ('de3af46a-3293-4aef-9e8f-52db67f88fc7', 'b2c3d4e5-6f7a-4c22-9d12-2e3f4a5b6c22', '08c1a9d8-6643-4dee-b5b4-33c6fa3ddf21', 'concept'::public.curated_course_node_type, 'From fieldnote to ethnographic claim', null, 3),
  ('f693d4b3-b230-4497-ac40-7b0ec5cb0d1a', 'b2c3d4e5-6f7a-4c22-9d12-2e3f4a5b6c22', null, 'topic'::public.curated_course_node_type, 'Ethics, Reflexivity, Positionality, Collaboration, and Representation', 'Anthropological knowledge is made through relationships. This unit teaches students to take ethics, power, positionality, and representation seriously from the start.', 2),
  ('67efa978-3f35-46d5-a00a-22e9e1421b28', 'b2c3d4e5-6f7a-4c22-9d12-2e3f4a5b6c22', 'f693d4b3-b230-4497-ac40-7b0ec5cb0d1a', 'subtopic'::public.curated_course_node_type, 'Research Ethics', 'Students learn the responsibilities that come with entering people''s lives, stories, places, and knowledge systems.', 0),
  ('e4e72230-5a88-421b-a8df-52fe2902e628', 'b2c3d4e5-6f7a-4c22-9d12-2e3f4a5b6c22', '67efa978-3f35-46d5-a00a-22e9e1421b28', 'concept'::public.curated_course_node_type, 'Consent and ongoing negotiation', null, 0),
  ('ecbe91f5-7075-4bae-9a3d-b6036f9f8a0b', 'b2c3d4e5-6f7a-4c22-9d12-2e3f4a5b6c22', '67efa978-3f35-46d5-a00a-22e9e1421b28', 'concept'::public.curated_course_node_type, 'Confidentiality and risk', null, 1),
  ('0e40833e-adb5-4bba-8a3a-d80aecae9da4', 'b2c3d4e5-6f7a-4c22-9d12-2e3f4a5b6c22', '67efa978-3f35-46d5-a00a-22e9e1421b28', 'concept'::public.curated_course_node_type, 'Do no harm and benefit sharing', null, 2),
