  ('5aa1241b-2fc0-41f2-95de-d0910081a0af', 'b2c3d4e5-6f7a-4c22-9d12-2e3f4a5b6c22', 'f693d4b3-b230-4497-ac40-7b0ec5cb0d1a', 'subtopic'::public.curated_course_node_type, 'Reflexivity and Positionality', 'The point is to recognize that researchers are part of the research situation.', 1),
