  ('09b2530e-70a1-4680-9833-2270b22e22ec', 'b2c3d4e5-6f7a-4c22-9d12-2e3f4a5b6c22', '2d983fce-9b37-426a-845f-abea532b174e', 'concept'::public.curated_course_node_type, 'Responsible return of findings', null, 3),
  ('585a7c07-d8f6-4a99-8c01-bfd98c27e30c', 'b2c3d4e5-6f7a-4c22-9d12-2e3f4a5b6c22', null, 'topic'::public.curated_course_node_type, 'Kinship, Households, Relatedness, Family, and Social Organization', 'Kinship is not just biology. Students learn how people make relatedness through marriage, descent, care, residence, adoption, reproduction, ritual, and everyday obligation.', 3),
