  ('7e997608-e6ca-4865-957c-525a67fc52d1', 'b2c3d4e5-6f7a-4c22-9d12-2e3f4a5b6c22', null, 'topic'::public.curated_course_node_type, 'Gender, Sexuality, Personhood, Embodiment, and the Life Course', 'This unit examines how gender, sexuality, bodies, personhood, and life stages are culturally made and politically contested.', 4),
