  ('665d7fe5-e499-461a-8d43-1c518576e850', 'b2c3d4e5-6f7a-4c22-9d12-2e3f4a5b6c22', '82a72eb0-296d-4941-a3f0-68b323bcc691', 'concept'::public.curated_course_node_type, 'Sex and gender distinction', null, 0),
