  ('51e0074b-8e6b-45c3-902e-30567b2cda77', 'b2c3d4e5-6f7a-4c22-9d12-2e3f4a5b6c22', '7e997608-e6ca-4865-957c-525a67fc52d1', 'subtopic'::public.curated_course_node_type, 'Sexuality and Personhood', 'The point is to understand sexuality and personhood as culturally meaningful, regulated, and lived.', 1),
