  ('b27ecb83-06c4-41b8-9b3d-3ab3896695e6', 'b2c3d4e5-6f7a-4c22-9d12-2e3f4a5b6c22', '51e0074b-8e6b-45c3-902e-30567b2cda77', 'concept'::public.curated_course_node_type, 'Personhood and selfhood', null, 1),
