  ('09611d9e-cb7b-40e6-b9b9-af77a0892e6f', 'b2c3d4e5-6f7a-4c22-9d12-2e3f4a5b6c22', 'a74e19ed-5419-4714-b4ff-f58514129a36', 'concept'::public.curated_course_node_type, 'Childhood and coming of age', null, 0),
