insert into public.curated_course_nodes (id, course_id, parent_id, node_type, title, description, sort_order)
values
  ('48591b06-18ac-4351-9410-f129ee45bcba', 'b2c3d4e5-6f7a-4c22-9d12-2e3f4a5b6c22', null, 'topic'::public.curated_course_node_type, 'Exchange, Labor, Value, Markets, Gifts, and Economic Life', 'Economic life is cultural life. Students learn how value, exchange, work, gifts, debt, markets, and household economies are embedded in relationships and moral worlds.', 5),
  ('981c6e42-1bac-41e1-b314-7f9ffcceec53', 'b2c3d4e5-6f7a-4c22-9d12-2e3f4a5b6c22', '48591b06-18ac-4351-9410-f129ee45bcba', 'subtopic'::public.curated_course_node_type, 'Subsistence and Livelihood', 'Students compare ways people make a living and organize resources.', 0),
  ('d0121115-685e-4ca6-96ce-07558e7edbae', 'b2c3d4e5-6f7a-4c22-9d12-2e3f4a5b6c22', '981c6e42-1bac-41e1-b314-7f9ffcceec53', 'concept'::public.curated_course_node_type, 'Foraging, pastoralism, horticulture, and agriculture', null, 0),
  ('38091348-e4cf-4663-9bff-20a4c540f7fc', 'b2c3d4e5-6f7a-4c22-9d12-2e3f4a5b6c22', '981c6e42-1bac-41e1-b314-7f9ffcceec53', 'concept'::public.curated_course_node_type, 'Industrial and postindustrial work', null, 1),
  ('765a3dc2-9af3-4ef3-9d24-2a10d87ffda1', 'b2c3d4e5-6f7a-4c22-9d12-2e3f4a5b6c22', '981c6e42-1bac-41e1-b314-7f9ffcceec53', 'concept'::public.curated_course_node_type, 'Informal economies', null, 2),
  ('40886d53-490c-46ee-8b01-f9ed0894eee2', 'b2c3d4e5-6f7a-4c22-9d12-2e3f4a5b6c22', '981c6e42-1bac-41e1-b314-7f9ffcceec53', 'concept'::public.curated_course_node_type, 'Household production and reproduction', null, 3),
