  ('914882e3-10f1-4f79-a607-fb2a3b092ac8', 'b2c3d4e5-6f7a-4c22-9d12-2e3f4a5b6c22', 'bf8358d9-d57e-4d81-82ab-ea59aa4f9db0', 'concept'::public.curated_course_node_type, 'Mauss and the gift', null, 0),
  ('eac18244-c616-41a2-9d90-4857c5b26126', 'b2c3d4e5-6f7a-4c22-9d12-2e3f4a5b6c22', 'bf8358d9-d57e-4d81-82ab-ea59aa4f9db0', 'concept'::public.curated_course_node_type, 'Reciprocity, redistribution, and market exchange', null, 1),
  ('0329a5ec-a720-4565-a7e2-3be7c483e4a7', 'b2c3d4e5-6f7a-4c22-9d12-2e3f4a5b6c22', 'bf8358d9-d57e-4d81-82ab-ea59aa4f9db0', 'concept'::public.curated_course_node_type, 'Debt and moral obligation', null, 2),
  ('a4624eb5-0f35-4857-b711-8724d7a19767', 'b2c3d4e5-6f7a-4c22-9d12-2e3f4a5b6c22', 'bf8358d9-d57e-4d81-82ab-ea59aa4f9db0', 'concept'::public.curated_course_node_type, 'Commodification and alienation', null, 3),
  ('6893f57c-58ac-4d93-a321-db5461d5a66f', 'b2c3d4e5-6f7a-4c22-9d12-2e3f4a5b6c22', '48591b06-18ac-4351-9410-f129ee45bcba', 'subtopic'::public.curated_course_node_type, 'Labor, Value, and Inequality', 'Students connect economic anthropology to capitalism, dispossession, development, and exploitation.', 2),
  ('8e651130-6d21-4c09-9107-8aeb0ccb4f33', 'b2c3d4e5-6f7a-4c22-9d12-2e3f4a5b6c22', '6893f57c-58ac-4d93-a321-db5461d5a66f', 'concept'::public.curated_course_node_type, 'Wage labor and precarity', null, 0),
  ('54ede7ba-e954-45ab-903b-443e148c3a1d', 'b2c3d4e5-6f7a-4c22-9d12-2e3f4a5b6c22', '6893f57c-58ac-4d93-a321-db5461d5a66f', 'concept'::public.curated_course_node_type, 'Care work and reproductive labor', null, 1),
  ('04012ae2-86f6-446e-9f7e-0718188445b3', 'b2c3d4e5-6f7a-4c22-9d12-2e3f4a5b6c22', '6893f57c-58ac-4d93-a321-db5461d5a66f', 'concept'::public.curated_course_node_type, 'Global supply chains', null, 2),
  ('2685cc57-9979-4a66-8b5c-d49a8835eb37', 'b2c3d4e5-6f7a-4c22-9d12-2e3f4a5b6c22', '6893f57c-58ac-4d93-a321-db5461d5a66f', 'concept'::public.curated_course_node_type, 'Class, race, gender, and labor regimes', null, 3),
  ('3afb2d9e-6192-4411-accb-0cd5b0be0cdb', 'b2c3d4e5-6f7a-4c22-9d12-2e3f4a5b6c22', null, 'topic'::public.curated_course_node_type, 'Political Authority, Law, Conflict, Violence, and Social Power', 'Political anthropology asks how power is organized, justified, resisted, and lived. Students examine authority from households and chiefs to states, law, bureaucracy, and violence.', 6),
  ('379d5071-d054-4add-a345-f335cc5d54ef', 'b2c3d4e5-6f7a-4c22-9d12-2e3f4a5b6c22', '3afb2d9e-6192-4411-accb-0cd5b0be0cdb', 'subtopic'::public.curated_course_node_type, 'Authority and Governance', 'Students learn that politics is not limited to formal states.', 0),
  ('942f367e-e18f-4ea0-9a72-b3fd870c153c', 'b2c3d4e5-6f7a-4c22-9d12-2e3f4a5b6c22', '379d5071-d054-4add-a345-f335cc5d54ef', 'concept'::public.curated_course_node_type, 'Bands, tribes, chiefdoms, and states', null, 0),
  ('ee0f2ce5-cedb-471a-b279-70284bcb84c9', 'b2c3d4e5-6f7a-4c22-9d12-2e3f4a5b6c22', '379d5071-d054-4add-a345-f335cc5d54ef', 'concept'::public.curated_course_node_type, 'Leadership and legitimacy', null, 1),
  ('f0aeaa97-155e-4b29-81a7-2bcffcf8eedb', 'b2c3d4e5-6f7a-4c22-9d12-2e3f4a5b6c22', '379d5071-d054-4add-a345-f335cc5d54ef', 'concept'::public.curated_course_node_type, 'Customary authority', null, 2),
  ('9badc2ed-bb8a-4fc4-a66b-af5babaa7457', 'b2c3d4e5-6f7a-4c22-9d12-2e3f4a5b6c22', '379d5071-d054-4add-a345-f335cc5d54ef', 'concept'::public.curated_course_node_type, 'Bureaucracy and administration', null, 3),
  ('feddbafc-8e79-477b-9aec-dcff58df611f', 'b2c3d4e5-6f7a-4c22-9d12-2e3f4a5b6c22', '3afb2d9e-6192-4411-accb-0cd5b0be0cdb', 'subtopic'::public.curated_course_node_type, 'Law, Citizenship, and Sovereignty', 'The point is to examine rules, rights, belonging, and exclusion anthropologically.', 1),
  ('95ce7c8f-01d7-4573-ac69-3770dd7481b2', 'b2c3d4e5-6f7a-4c22-9d12-2e3f4a5b6c22', 'feddbafc-8e79-477b-9aec-dcff58df611f', 'concept'::public.curated_course_node_type, 'Legal pluralism', null, 0),
  ('b47fabb8-01d3-4baa-a427-cef997d1aaf5', 'b2c3d4e5-6f7a-4c22-9d12-2e3f4a5b6c22', 'feddbafc-8e79-477b-9aec-dcff58df611f', 'concept'::public.curated_course_node_type, 'Citizenship and statelessness', null, 1),
