  ('fef13e72-0d95-4e24-a913-921e76b6a4c5', 'b2c3d4e5-6f7a-4c22-9d12-2e3f4a5b6c22', 'a67f76de-ae2f-4c05-9d05-527210649a65', 'concept'::public.curated_course_node_type, 'Everyday violence', null, 0),
  ('37ae29e9-1668-4b25-93b5-9107c7f60c82', 'b2c3d4e5-6f7a-4c22-9d12-2e3f4a5b6c22', 'a67f76de-ae2f-4c05-9d05-527210649a65', 'concept'::public.curated_course_node_type, 'Structural violence', null, 1),
  ('3107f9c2-cf98-454c-9efe-e818e2b4af64', 'b2c3d4e5-6f7a-4c22-9d12-2e3f4a5b6c22', 'a67f76de-ae2f-4c05-9d05-527210649a65', 'concept'::public.curated_course_node_type, 'War, security, and displacement', null, 2),
