  ('ffb293b5-0eef-442f-9669-3d1a88522dad', 'b2c3d4e5-6f7a-4c22-9d12-2e3f4a5b6c22', null, 'topic'::public.curated_course_node_type, 'Ritual, Belief, Religion, Symbolism, and Meaning-Making', 'Ritual and belief reveal how people make worlds meaningful. Students learn to interpret symbols, practices, sacred spaces, healing, myth, and performance without reducing them to superstition.', 7),
  ('e885d792-351e-4f4e-8de1-f27b1f8a8c8e', 'b2c3d4e5-6f7a-4c22-9d12-2e3f4a5b6c22', 'ffb293b5-0eef-442f-9669-3d1a88522dad', 'subtopic'::public.curated_course_node_type, 'Ritual and Symbol', 'Students learn how ritual organizes time, transition, belonging, and authority.', 0),
  ('79922ecd-94f5-4628-954f-e6f60e4ee3fb', 'b2c3d4e5-6f7a-4c22-9d12-2e3f4a5b6c22', 'e885d792-351e-4f4e-8de1-f27b1f8a8c8e', 'concept'::public.curated_course_node_type, 'Rites of passage', null, 0),
