  ('0bbe60f5-d599-413b-b37c-5ae39f2d4b2e', 'b2c3d4e5-6f7a-4c22-9d12-2e3f4a5b6c22', null, 'topic'::public.curated_course_node_type, 'Race, Ethnicity, Nationalism, Colonialism, and Indigeneity', 'This unit examines how race, ethnicity, nation, colonialism, and indigeneity are made through history, power, classification, land, memory, and resistance.', 8),
