  ('5d6dfc14-3e2d-414a-9c1b-bd055d4c450a', 'b2c3d4e5-6f7a-4c22-9d12-2e3f4a5b6c22', null, 'topic'::public.curated_course_node_type, 'Language, Communication, Identity, Performance, and Ideology', 'Language is social action. Students learn how speech, silence, translation, performance, code-switching, and language ideology make identity and power visible.', 9),
