  ('07609399-b1f5-49fa-85ee-0e86f443f0f9', 'b2c3d4e5-6f7a-4c22-9d12-2e3f4a5b6c22', '8fa12142-6cb0-42f7-b09a-0aa533c6576e', 'concept'::public.curated_course_node_type, 'Infrastructure and inequality', null, 3),
  ('78086dda-70ef-416a-9e0a-20a7d59c51b3', 'b2c3d4e5-6f7a-4c22-9d12-2e3f4a5b6c22', null, 'topic'::public.curated_course_node_type, 'Anthropological Theory: Boas, Functionalism, Structuralism, Practice, Feminist and Postcolonial Critiques', 'Theory helps students name what they see in ethnographic cases. This unit maps major anthropological schools and the debates that shape contemporary cultural anthropology.', 13),
  ('19035d50-276c-4242-b1f1-aa98fc8a2a5b', 'b2c3d4e5-6f7a-4c22-9d12-2e3f4a5b6c22', '78086dda-70ef-416a-9e0a-20a7d59c51b3', 'subtopic'::public.curated_course_node_type, 'Foundational Theory Traditions', 'Students learn how anthropology moved from evolutionism to historical particularism, functionalism, and structuralism.', 0),
  ('a8ee13ca-d92e-40cb-b800-a0fede78578f', 'b2c3d4e5-6f7a-4c22-9d12-2e3f4a5b6c22', '19035d50-276c-4242-b1f1-aa98fc8a2a5b', 'concept'::public.curated_course_node_type, 'Evolutionism and critique', null, 0),
  ('fb1577d7-2898-43fb-9440-5c1c0796e26c', 'b2c3d4e5-6f7a-4c22-9d12-2e3f4a5b6c22', '19035d50-276c-4242-b1f1-aa98fc8a2a5b', 'concept'::public.curated_course_node_type, 'Boas and historical particularism', null, 1),
  ('f9a25d5f-a9ad-489a-8a45-0373392e9120', 'b2c3d4e5-6f7a-4c22-9d12-2e3f4a5b6c22', '19035d50-276c-4242-b1f1-aa98fc8a2a5b', 'concept'::public.curated_course_node_type, 'Functionalism and structural functionalism', null, 2),
  ('63dee1af-dc15-452f-948b-3edada698a99', 'b2c3d4e5-6f7a-4c22-9d12-2e3f4a5b6c22', '19035d50-276c-4242-b1f1-aa98fc8a2a5b', 'concept'::public.curated_course_node_type, 'Structuralism and symbolic anthropology', null, 3),
  ('0b8b10dc-8171-456b-b064-bd3bee897fda', 'b2c3d4e5-6f7a-4c22-9d12-2e3f4a5b6c22', '78086dda-70ef-416a-9e0a-20a7d59c51b3', 'subtopic'::public.curated_course_node_type, 'Practice, Political Economy, and Interpretation', 'The gist is learning how theory connects meaning, agency, power, and material life.', 1),
  ('0f38b8ca-06f7-4ccd-ab40-c3988e6afcca', 'b2c3d4e5-6f7a-4c22-9d12-2e3f4a5b6c22', '0b8b10dc-8171-456b-b064-bd3bee897fda', 'concept'::public.curated_course_node_type, 'Geertz and thick description', null, 0),
