  ('2f47692d-54f2-4cd3-a7a9-304794128651', 'b2c3d4e5-6f7a-4c22-9d12-2e3f4a5b6c22', '0b8b10dc-8171-456b-b064-bd3bee897fda', 'concept'::public.curated_course_node_type, 'Marxist and political economy approaches', null, 2),
  ('6caf8fb8-7739-4a07-b9ae-ea48c6f0c8b7', 'b2c3d4e5-6f7a-4c22-9d12-2e3f4a5b6c22', '0b8b10dc-8171-456b-b064-bd3bee897fda', 'concept'::public.curated_course_node_type, 'Agency, structure, and habitus', null, 3),
  ('2f14ae96-18f2-49e3-bad5-08e1044677d8', 'b2c3d4e5-6f7a-4c22-9d12-2e3f4a5b6c22', '78086dda-70ef-416a-9e0a-20a7d59c51b3', 'subtopic'::public.curated_course_node_type, 'Contemporary Critiques and Turns', 'Students learn how feminist, postcolonial, Indigenous, science studies, and multispecies work transformed the field.', 2),
  ('d1147e62-0123-4ebc-a0bd-dd6f182c7d82', 'b2c3d4e5-6f7a-4c22-9d12-2e3f4a5b6c22', '2f14ae96-18f2-49e3-bad5-08e1044677d8', 'concept'::public.curated_course_node_type, 'Feminist anthropology', null, 0),
