  ('2cfa0916-7f58-44e2-8dc8-36c3772f1888', 'b2c3d4e5-6f7a-4c22-9d12-2e3f4a5b6c22', '2f14ae96-18f2-49e3-bad5-08e1044677d8', 'concept'::public.curated_course_node_type, 'Ontological and multispecies turns', null, 3),
  ('e593ba70-ffec-4f1f-810e-98314b992c08', 'b2c3d4e5-6f7a-4c22-9d12-2e3f4a5b6c22', null, 'topic'::public.curated_course_node_type, 'Applied and Public Anthropology: Design, Policy, Advocacy, and Ethnographic Writing', 'The final unit asks students to use anthropological insight publicly and responsibly. They learn to write ethnographically, translate findings, and imagine anthropology beyond the classroom.', 14),
  ('75741a1a-ed67-4e28-a28f-024cd7ed1ce6', 'b2c3d4e5-6f7a-4c22-9d12-2e3f4a5b6c22', 'e593ba70-ffec-4f1f-810e-98314b992c08', 'subtopic'::public.curated_course_node_type, 'Applied and Public Anthropology', 'Students learn how anthropologists work in policy, health, design, museums, education, development, environment, and advocacy.', 0),
