  ('c8b00ecc-f074-4fb0-8974-979cee5b181e', 'b2c3d4e5-6f7a-4c22-9d12-2e3f4a5b6c22', '75741a1a-ed67-4e28-a28f-024cd7ed1ce6', 'concept'::public.curated_course_node_type, 'Needs assessment and program evaluation', null, 3),
  ('5e73b9ce-2ff7-4199-bdae-e37727c82acf', 'b2c3d4e5-6f7a-4c22-9d12-2e3f4a5b6c22', 'e593ba70-ffec-4f1f-810e-98314b992c08', 'subtopic'::public.curated_course_node_type, 'Design, Policy, and Professional Practice', 'The point is to connect ethnographic methods to real-world decision-making without flattening cultural complexity.', 1),
  ('c7a8893b-dc24-4efb-bdb0-084749e73a10', 'b2c3d4e5-6f7a-4c22-9d12-2e3f4a5b6c22', '5e73b9ce-2ff7-4199-bdae-e37727c82acf', 'concept'::public.curated_course_node_type, 'Design anthropology and UX research', null, 0),
