update public.learning_paths
set
  title = 'Cultural Anthropology',
  goal = 'Cultural Anthropology',
  summary = 'This course introduces cultural anthropology as the comparative, ethnographic study of human meaning, practice, power, and social life. Students examine culture, fieldwork, ethics, kinship, gender, economy, politics, ritual, race, language, globalization, medicine, environment, technology, theory, and applied/public anthropology. The course emphasizes cultural relativism, critical comparison, reflexive methods, ethical representation, and the public relevance of anthropological insight.',
  data = $cuanjson${"slug": "cultural-anthropology", "title": "Cultural Anthropology", "description": "This course introduces cultural anthropology as the comparative, ethnographic study of human meaning, practice, power, and social life. Students examine culture, fieldwork, ethics, kinship, gender, economy, politics, ritual, race, language, globalization, medicine, environment, technology, theory, and applied/public anthropology. The course emphasizes cultural relativism, critical comparison, reflexive methods, ethical representation, and the public relevance of anthropological insight.", "topics": [{"id": "84bc4a86-edd4-4b13-8386-5a91b29e4b65", "type": "topic", "title": "Anthropology, the Culture Concept, and Holistic Human Inquiry", "description": "This unit introduces anthropology as a way of asking what it means to be human across time, place, biology, language, culture, and power. Students learn that culture is useful, contested, and never static.", "children": [{"id": "37bb2379-3c82-4106-be91-312a8e7517a4", "type": "subtopic", "title": "Anthropology's Holistic Frame", "children": [{"id": "13de2b02-328d-4053-b92b-2c4c1d31ad00", "type": "concept", "title": "Four-field anthropology"}, {"id": "9aabfc68-3c4e-4f9c-9338-58b35b46ccdf", "type": "concept", "title": "Comparison and relativism"}, {"id": "de32f5f6-e3fd-4fdf-a28b-6986ebcb01f9", "type": "concept", "title": "Human variation and commonality"}, {"id": "92861f93-f994-4c49-9178-e78cd152ca66", "type": "concept", "title": "Anthropology as field-based inquiry"}], "description": "Students learn why anthropology connects cultural, biological, archaeological, and linguistic evidence instead of isolating social life from bodies, histories, and environments."}, {"id": "8e5c91a9-dc0a-4b3c-8c25-c66f26afc57d", "type": "subtopic", "title": "The Culture Concept", "children": [{"id": "5c365959-d5c7-4db0-a61b-e3f14c61a670", "type": "concept", "title": "Culture as meaning and practice"}, {"id": "9dd447a0-ec4f-4400-9064-2955ca86e6c0", "type": "concept", "title": "Norms, values, symbols, and institutions"}, {"id": "6ad2b0f9-ed72-4b5c-abfb-5608873810a7", "type": "concept", "title": "Culture as process rather than container"}, {"id": "6e009b37-3284-461c-8167-bb5d4c15ef36", "type": "concept", "title": "Critiques of bounded culture models"}], "description": "The point is to understand culture as learned, shared, contested, embodied, and historically produced."}, {"id": "381c03aa-d135-400b-a42c-d728088b0c7b", "type": "subtopic", "title": "Ethnocentrism and Cultural Relativism", "children": [{"id": "86483ed0-71ea-4477-a1bc-1701b4e67032", "type": "concept", "title": "Ethnocentrism"}, {"id": "f2912278-2363-466e-b443-c58dacb198bf", "type": "concept", "title": "Methodological relativism"}, {"id": "5bac3310-af92-4a5f-84a3-c8f88a5008e1", "type": "concept", "title": "Moral relativism debates"}, {"id": "ec53eb40-644d-44dd-b71c-2cb65360100f", "type": "concept", "title": "Comparison without hierarchy"}], "description": "Students learn to suspend easy judgment while still making ethical and analytical distinctions."}]}, {"id": "d028ace4-e0ba-4dfe-8ee6-2e465a5bd0c2", "type": "topic", "title": "Ethnography, Participant Observation, and Fieldwork as Method", "description": "Ethnography is the signature method of cultural anthropology. Students learn how long-term attention, participation, listening, and writing turn everyday life into evidence.", "children": [{"id": "9e8be171-1177-4da3-b23c-fd14f1c353d9", "type": "subtopic", "title": "Participant Observation", "children": [{"id": "53cac185-a7d8-40ad-bf20-b82f4163ffdf", "type": "concept", "title": "Participation and observation"}, {"id": "2cb59cfb-9c06-4e79-9514-ae98901e5874", "type": "concept", "title": "Rapport and field relationships"}, {"id": "00821d28-60ab-4c40-885d-cb50982699be", "type": "concept", "title": "Everyday life as evidence"}, {"id": "2d710f44-afe1-4bc8-afaf-e0e346977982", "type": "concept", "title": "Fieldsite boundaries and multi-sited research"}], "description": "Students learn why anthropologists study with people rather than only about people."}, {"id": "8ce4d366-1637-4385-ad2d-a895052bedef", "type": "subtopic", "title": "Interviews and Fieldnotes", "children": [{"id": "be599eab-9ca7-47ed-b330-dad48d326f23", "type": "concept", "title": "Open-ended interviews"}, {"id": "28c0f51f-f785-48a4-bc56-f96bc2f89b1d", "type": "concept", "title": "Oral histories and life histories"}, {"id": "dceb4186-2f31-4e30-9800-9bcc594fd89c", "type": "concept", "title": "Jottings and expanded fieldnotes"}, {"id": "0f7e9f4d-d149-429e-9cc3-f0fedd2638ce", "type": "concept", "title": "Thick description"}], "description": "The gist is learning how questions, listening, recording, and writing shape the evidence produced."}, {"id": "08c1a9d8-6643-4dee-b5b4-33c6fa3ddf21", "type": "subtopic", "title": "Ethnographic Analysis", "children": [{"id": "b0d5259d-e2da-4d3a-9376-a93b9a2cb078", "type": "concept", "title": "Coding and memoing"}, {"id": "91ec9a69-b4d6-4493-b5cf-8ab3cfa8ad7d", "type": "concept", "title": "Emic and etic perspectives"}, {"id": "ec5a9d72-a219-4064-81db-6ca02ad46342", "type": "concept", "title": "Pattern, contradiction, and case"}, {"id": "de3af46a-3293-4aef-9e8f-52db67f88fc7", "type": "concept", "title": "From fieldnote to ethnographic claim"}], "description": "Students learn how field materials become concepts, arguments, and written accounts."}]}, {"id": "f693d4b3-b230-4497-ac40-7b0ec5cb0d1a", "type": "topic", "title": "Ethics, Reflexivity, Positionality, Collaboration, and Representation", "description": "Anthropological knowledge is made through relationships. This unit teaches students to take ethics, power, positionality, and representation seriously from the start.", "children": [{"id": "67efa978-3f35-46d5-a00a-22e9e1421b28", "type": "subtopic", "title": "Research Ethics", "children": [{"id": "e4e72230-5a88-421b-a8df-52fe2902e628", "type": "concept", "title": "Consent and ongoing negotiation"}, {"id": "ecbe91f5-7075-4bae-9a3d-b6036f9f8a0b", "type": "concept", "title": "Confidentiality and risk"}, {"id": "0e40833e-adb5-4bba-8a3a-d80aecae9da4", "type": "concept", "title": "Do no harm and benefit sharing"}, {"id": "8f2c36a7-0a9b-43c2-bffc-ab24df54865c", "type": "concept", "title": "AAA ethics and IRB basics"}], "description": "Students learn the responsibilities that come with entering people's lives, stories, places, and knowledge systems."}, {"id": "5aa1241b-2fc0-41f2-95de-d0910081a0af", "type": "subtopic", "title": "Reflexivity and Positionality", "children": [{"id": "cd129622-7999-44c9-80c2-b24fbd76180c", "type": "concept", "title": "Researcher identity and access"}, {"id": "cb469804-a851-472c-a742-3cadca7ef346", "type": "concept", "title": "Power and asymmetry"}, {"id": "e4a2c7f2-aaf5-4409-a9b3-0790b8d54e89", "type": "concept", "title": "Reflexive fieldnotes"}, {"id": "7470928b-2a2f-4861-b6fc-1e209156dc28", "type": "concept", "title": "Accountability to participants and publics"}], "description": "The point is to recognize that researchers are part of the research situation."}, {"id": "2d983fce-9b37-426a-845f-abea532b174e", "type": "subtopic", "title": "Representation and Collaboration", "children": [{"id": "2fa502bd-91e1-4a20-8779-be9ff7a274e3", "type": "concept", "title": "Voice, translation, and authority"}, {"id": "3bb19efa-34b5-4d31-b237-2086c31f1407", "type": "concept", "title": "Collaborative and community-based research"}, {"id": "83d471f3-ca67-4fd8-84ef-c78c4ea2decd", "type": "concept", "title": "Data sovereignty and cultural heritage"}, {"id": "09b2530e-70a1-4680-9833-2270b22e22ec", "type": "concept", "title": "Responsible return of findings"}], "description": "Students learn why writing about others is never neutral."}]}, {"id": "585a7c07-d8f6-4a99-8c01-bfd98c27e30c", "type": "topic", "title": "Kinship, Households, Relatedness, Family, and Social Organization", "description": "Kinship is not just biology. Students learn how people make relatedness through marriage, descent, care, residence, adoption, reproduction, ritual, and everyday obligation.", "children": [{"id": "cf31267f-adcd-4c4b-b7b2-838daf110f98", "type": "subtopic", "title": "Kinship Systems", "children": [{"id": "447f3bdf-5163-4abe-8681-8d6a65b8f71c", "type": "concept", "title": "Descent and lineage"}, {"id": "88243057-225a-4069-9121-a8e72e343315", "type": "concept", "title": "Marriage and alliance"}, {"id": "8f6b3a6a-55a3-4b22-9ca0-cb9bea1423fa", "type": "concept", "title": "Residence patterns"}, {"id": "7bc350ab-81b2-473c-92b2-faa9dfb82c46", "type": "concept", "title": "Kinship terminology"}], "description": "Students learn how societies organize belonging, descent, inheritance, and obligation."}, {"id": "0c6a1a65-7f4f-43b1-9cb5-fa3033e942e8", "type": "subtopic", "title": "Households and Care", "children": [{"id": "4cfa6cfc-be75-4a7c-a363-521d2cec9f16", "type": "concept", "title": "Domestic labor"}, {"id": "54f2bacb-6abc-479d-9171-52934c365868", "type": "concept", "title": "Eldercare and childcare"}, {"id": "53b4cbea-0ed7-48c4-9b27-037ac74a5562", "type": "concept", "title": "Household economies"}, {"id": "420b53ce-26de-4619-a2c5-d8b9164428c9", "type": "concept", "title": "Relatedness beyond the nuclear family"}], "description": "The gist is understanding households as social, economic, emotional, and political units."}, {"id": "f0ba8279-ad95-4ea9-8c48-2a612f008458", "type": "subtopic", "title": "Reproduction and New Kinship", "children": [{"id": "600d61f2-c340-41fb-82f8-fff05d92869d", "type": "concept", "title": "Adoption and fostering"}, {"id": "0037ef6c-0618-4dae-a118-2b5666cc0710", "type": "concept", "title": "Assisted reproduction"}, {"id": "501a093e-d4bd-4cda-9770-9d36cccb2df7", "type": "concept", "title": "Queer kinship"}, {"id": "9470d337-d20c-47d4-8ffb-67be2d184702", "type": "concept", "title": "Transnational families"}], "description": "Students explore how reproduction, technology, migration, and law transform kinship."}]}, {"id": "7e997608-e6ca-4865-957c-525a67fc52d1", "type": "topic", "title": "Gender, Sexuality, Personhood, Embodiment, and the Life Course", "description": "This unit examines how gender, sexuality, bodies, personhood, and life stages are culturally made and politically contested.", "children": [{"id": "82a72eb0-296d-4941-a3f0-68b323bcc691", "type": "subtopic", "title": "Gender as Social Practice", "children": [{"id": "665d7fe5-e499-461a-8d43-1c518576e850", "type": "concept", "title": "Sex and gender distinction"}, {"id": "a0e3544a-7383-4a66-af1e-c776c8bef495", "type": "concept", "title": "Gender roles and socialization"}, {"id": "377c4c28-ebfc-4837-bcc9-c4c85e6f0fee", "type": "concept", "title": "Gender variance and third-gender categories"}, {"id": "99c7eb0e-4671-4fe6-a780-28e8c77f0cee", "type": "concept", "title": "Gendered labor and power"}], "description": "Students learn to analyze gender as performed, institutionalized, and embodied."}, {"id": "51e0074b-8e6b-45c3-902e-30567b2cda77", "type": "subtopic", "title": "Sexuality and Personhood", "children": [{"id": "2378f111-4b8a-434c-a896-b194a05f5583", "type": "concept", "title": "Sexual norms and identities"}, {"id": "b27ecb83-06c4-41b8-9b3d-3ab3896695e6", "type": "concept", "title": "Personhood and selfhood"}, {"id": "db34d4d1-9a64-4c1a-9d56-0a1556903b99", "type": "concept", "title": "Desire, respectability, and stigma"}, {"id": "18ed70cb-e6bb-4f20-9e31-b2a4d0fba513", "type": "concept", "title": "Rights, law, and social recognition"}], "description": "The point is to understand sexuality and personhood as culturally meaningful, regulated, and lived."}, {"id": "a74e19ed-5419-4714-b4ff-f58514129a36", "type": "subtopic", "title": "Embodiment and the Life Course", "children": [{"id": "09611d9e-cb7b-40e6-b9b9-af77a0892e6f", "type": "concept", "title": "Childhood and coming of age"}, {"id": "7f219078-abaf-437f-8227-82bcc6980bc8", "type": "concept", "title": "Bodies, beauty, and discipline"}, {"id": "f36daa9c-978c-4ad4-a99d-3aecd3e66d4c", "type": "concept", "title": "Disability and difference"}, {"id": "b4be6df9-54c5-4efc-acbb-80e15cc448ce", "type": "concept", "title": "Aging, death, and memory"}], "description": "Students learn how bodies are shaped by culture, inequality, care, aging, and ritual."}]}, {"id": "48591b06-18ac-4351-9410-f129ee45bcba", "type": "topic", "title": "Exchange, Labor, Value, Markets, Gifts, and Economic Life", "description": "Economic life is cultural life. Students learn how value, exchange, work, gifts, debt, markets, and household economies are embedded in relationships and moral worlds.", "children": [{"id": "981c6e42-1bac-41e1-b314-7f9ffcceec53", "type": "subtopic", "title": "Subsistence and Livelihood", "children": [{"id": "d0121115-685e-4ca6-96ce-07558e7edbae", "type": "concept", "title": "Foraging, pastoralism, horticulture, and agriculture"}, {"id": "38091348-e4cf-4663-9bff-20a4c540f7fc", "type": "concept", "title": "Industrial and postindustrial work"}, {"id": "765a3dc2-9af3-4ef3-9d24-2a10d87ffda1", "type": "concept", "title": "Informal economies"}, {"id": "40886d53-490c-46ee-8b01-f9ed0894eee2", "type": "concept", "title": "Household production and reproduction"}], "description": "Students compare ways people make a living and organize resources."}, {"id": "bf8358d9-d57e-4d81-82ab-ea59aa4f9db0", "type": "subtopic", "title": "Gifts, Commodities, and Debt", "children": [{"id": "914882e3-10f1-4f79-a607-fb2a3b092ac8", "type": "concept", "title": "Mauss and the gift"}, {"id": "eac18244-c616-41a2-9d90-4857c5b26126", "type": "concept", "title": "Reciprocity, redistribution, and market exchange"}, {"id": "0329a5ec-a720-4565-a7e2-3be7c483e4a7", "type": "concept", "title": "Debt and moral obligation"}, {"id": "a4624eb5-0f35-4857-b711-8724d7a19767", "type": "concept", "title": "Commodification and alienation"}], "description": "The gist is learning that exchange creates relationships, obligation, hierarchy, and meaning."}, {"id": "6893f57c-58ac-4d93-a321-db5461d5a66f", "type": "subtopic", "title": "Labor, Value, and Inequality", "children": [{"id": "8e651130-6d21-4c09-9107-8aeb0ccb4f33", "type": "concept", "title": "Wage labor and precarity"}, {"id": "54ede7ba-e954-45ab-903b-443e148c3a1d", "type": "concept", "title": "Care work and reproductive labor"}, {"id": "04012ae2-86f6-446e-9f7e-0718188445b3", "type": "concept", "title": "Global supply chains"}, {"id": "2685cc57-9979-4a66-8b5c-d49a8835eb37", "type": "concept", "title": "Class, race, gender, and labor regimes"}], "description": "Students connect economic anthropology to capitalism, dispossession, development, and exploitation."}]}, {"id": "3afb2d9e-6192-4411-accb-0cd5b0be0cdb", "type": "topic", "title": "Political Authority, Law, Conflict, Violence, and Social Power", "description": "Political anthropology asks how power is organized, justified, resisted, and lived. Students examine authority from households and chiefs to states, law, bureaucracy, and violence.", "children": [{"id": "379d5071-d054-4add-a345-f335cc5d54ef", "type": "subtopic", "title": "Authority and Governance", "children": [{"id": "942f367e-e18f-4ea0-9a72-b3fd870c153c", "type": "concept", "title": "Bands, tribes, chiefdoms, and states"}, {"id": "ee0f2ce5-cedb-471a-b279-70284bcb84c9", "type": "concept", "title": "Leadership and legitimacy"}, {"id": "f0aeaa97-155e-4b29-81a7-2bcffcf8eedb", "type": "concept", "title": "Customary authority"}, {"id": "9badc2ed-bb8a-4fc4-a66b-af5babaa7457", "type": "concept", "title": "Bureaucracy and administration"}], "description": "Students learn that politics is not limited to formal states."}, {"id": "feddbafc-8e79-477b-9aec-dcff58df611f", "type": "subtopic", "title": "Law, Citizenship, and Sovereignty", "children": [{"id": "95ce7c8f-01d7-4573-ac69-3770dd7481b2", "type": "concept", "title": "Legal pluralism"}, {"id": "b47fabb8-01d3-4baa-a427-cef997d1aaf5", "type": "concept", "title": "Citizenship and statelessness"}, {"id": "43f5b807-7499-4655-af51-3fde11240945", "type": "concept", "title": "Borders and documentation"}, {"id": "b2e1ea48-0402-4a5c-99cb-9b3efbff2cf0", "type": "concept", "title": "Indigenous sovereignty"}], "description": "The point is to examine rules, rights, belonging, and exclusion anthropologically."}, {"id": "a67f76de-ae2f-4c05-9d05-527210649a65", "type": "subtopic", "title": "Conflict and Violence", "children": [{"id": "fef13e72-0d95-4e24-a913-921e76b6a4c5", "type": "concept", "title": "Everyday violence"}, {"id": "37ae29e9-1668-4b25-93b5-9107c7f60c82", "type": "concept", "title": "Structural violence"}, {"id": "3107f9c2-cf98-454c-9efe-e818e2b4af64", "type": "concept", "title": "War, security, and displacement"}, {"id": "f3028d23-4557-41d6-8715-ac0317fd5472", "type": "concept", "title": "Resistance and social movements"}], "description": "Students learn how violence is social, historical, symbolic, and institutional."}]}, {"id": "ffb293b5-0eef-442f-9669-3d1a88522dad", "type": "topic", "title": "Ritual, Belief, Religion, Symbolism, and Meaning-Making", "description": "Ritual and belief reveal how people make worlds meaningful. Students learn to interpret symbols, practices, sacred spaces, healing, myth, and performance without reducing them to superstition.", "children": [{"id": "e885d792-351e-4f4e-8de1-f27b1f8a8c8e", "type": "subtopic", "title": "Ritual and Symbol", "children": [{"id": "79922ecd-94f5-4628-954f-e6f60e4ee3fb", "type": "concept", "title": "Rites of passage"}, {"id": "3882e0aa-6282-466f-a225-ef72ff7cc510", "type": "concept", "title": "Sacred and profane"}, {"id": "0583d715-f277-4f17-b2ca-926aa9aadfcb", "type": "concept", "title": "Symbolic action"}, {"id": "51641e77-afc2-44b1-b54f-1cf2fc2ab89d", "type": "concept", "title": "Performance and repetition"}], "description": "Students learn how ritual organizes time, transition, belonging, and authority."}, {"id": "d0bd7abb-c3c2-426c-9473-2f3bf2885c31", "type": "subtopic", "title": "Religion and Cosmology", "children": [{"id": "8a718e84-d312-4e41-b123-7d58fb70a4a3", "type": "concept", "title": "Myth and worldview"}, {"id": "b2758e46-1eea-470b-b9d0-0cb1a1a49f1c", "type": "concept", "title": "Spirits, ancestors, and deities"}, {"id": "7056f0c1-015a-4ea9-8ef1-b584bba7aeb4", "type": "concept", "title": "Magic, witchcraft, and healing"}, {"id": "cd499d46-3da4-47c9-82ba-c794f010031e", "type": "concept", "title": "Secularism and religious change"}], "description": "The gist is understanding belief systems as lived social worlds."}, {"id": "d0faeee2-1c58-4b99-b742-1f6ef257ec22", "type": "subtopic", "title": "Meaning, Power, and Interpretation", "children": [{"id": "3eb64f36-d45c-43d2-b37d-9b095fbef730", "type": "concept", "title": "Interpretive anthropology"}, {"id": "e504ee5f-ad34-4259-8a45-0223cd718d0a", "type": "concept", "title": "Ritual and social order"}, {"id": "1592e35e-d5c3-4513-9966-9e00e414b03e", "type": "concept", "title": "Religion and politics"}, {"id": "ccf41d03-285f-4efe-9e19-04ab76a7978c", "type": "concept", "title": "Embodied belief and material religion"}], "description": "Students learn that symbols can unify, contest, discipline, or transform social life."}]}, {"id": "0bbe60f5-d599-413b-b37c-5ae39f2d4b2e", "type": "topic", "title": "Race, Ethnicity, Nationalism, Colonialism, and Indigeneity", "description": "This unit examines how race, ethnicity, nation, colonialism, and indigeneity are made through history, power, classification, land, memory, and resistance.", "children": [{"id": "d7c5523d-384d-434c-b92d-6e9b8c58212b", "type": "subtopic", "title": "Race and Ethnicity", "children": [{"id": "dc67fcd6-2ea4-49fa-88c7-d8839823cb8f", "type": "concept", "title": "Racial formation"}, {"id": "4e3be96d-e1da-4e74-89d4-100ff4df77d3", "type": "concept", "title": "Ethnicity and boundary-making"}, {"id": "77692ef0-d9dd-400d-89c0-ef3ecbb5d11c", "type": "concept", "title": "Racism and classification"}, {"id": "30a9e7e7-0bed-43e3-b7c5-b73c479727ba", "type": "concept", "title": "Diaspora and identity"}], "description": "Students learn race and ethnicity as historical and political formations, not natural facts."}, {"id": "028a9b73-cdf3-43ce-8f66-8c580397f8a0", "type": "subtopic", "title": "Nationalism and Belonging", "children": [{"id": "87292cba-76c7-479c-b87e-7d8450a01bfa", "type": "concept", "title": "Imagined communities"}, {"id": "699c56b9-636e-414e-b98e-e96ad4e1e6ee", "type": "concept", "title": "Citizenship and exclusion"}, {"id": "0bdc0fa6-aa46-4a12-ac70-484d980242c1", "type": "concept", "title": "Flags, monuments, and memory"}, {"id": "a3562150-c721-4d1b-bff9-122a6456f019", "type": "concept", "title": "Minorities and nation-states"}], "description": "The point is to understand how nations are imagined, narrated, and enforced."}, {"id": "c3333312-e49e-46d7-981a-720f24c949e5", "type": "subtopic", "title": "Colonialism and Indigeneity", "children": [{"id": "b4f341e9-813d-45c0-a82f-2d085801239c", "type": "concept", "title": "Settler colonialism"}, {"id": "a2adeef1-adc4-4c10-a8b5-0ded617794b9", "type": "concept", "title": "Indigenous sovereignty"}, {"id": "588129dc-5fe4-4cfd-a1f4-17ce4c13fae5", "type": "concept", "title": "Land, extraction, and heritage"}, {"id": "9fe33d10-b457-4c3c-8e68-2b28deb31c93", "type": "concept", "title": "Decolonizing anthropology"}], "description": "Students learn how colonial histories shape contemporary inequality, culture, land, and knowledge."}]}, {"id": "5d6dfc14-3e2d-414a-9c1b-bd055d4c450a", "type": "topic", "title": "Language, Communication, Identity, Performance, and Ideology", "description": "Language is social action. Students learn how speech, silence, translation, performance, code-switching, and language ideology make identity and power visible.", "children": [{"id": "1be1e77a-d85b-43c1-ac7b-4a246c2dcc2c", "type": "subtopic", "title": "Language in Social Life", "children": [{"id": "60df75f5-6544-4fcc-86d1-c1cfb0639953", "type": "concept", "title": "Speech communities"}, {"id": "6e694cc4-0745-4195-8f43-8dc470b5b8ab", "type": "concept", "title": "Registers and genres"}, {"id": "fb557075-23bd-437b-a485-ff393cb96f61", "type": "concept", "title": "Performance and interaction"}, {"id": "de2d93f2-bae8-405b-b01e-19408ad46edb", "type": "concept", "title": "Language socialization"}], "description": "Students learn that language does things: it indexes identity, creates relationships, and organizes social worlds."}, {"id": "beee7844-df1e-4deb-9bf4-b2d12df4e984", "type": "subtopic", "title": "Language Ideology and Power", "children": [{"id": "f2a5e1b9-e31c-4ba0-8d53-f1cec27f48c2", "type": "concept", "title": "Standard language ideology"}, {"id": "c7550c6a-4180-4dfb-bc8e-36ebd366df71", "type": "concept", "title": "Accent and discrimination"}, {"id": "c2679c9e-c5f7-4706-82ae-bf22cf7938c7", "type": "concept", "title": "Multilingualism and code-switching"}, {"id": "f7ad0516-f6ec-400f-9cec-a490f8ba437f", "type": "concept", "title": "Language, race, gender, and class"}], "description": "The gist is understanding how ideas about language reproduce hierarchy."}, {"id": "f038e758-b178-478c-87dc-82a047b4ef6b", "type": "subtopic", "title": "Translation and Communication", "children": [{"id": "b272241f-a165-4003-b70c-f17b2bdcd7b3", "type": "concept", "title": "Meaning and context"}, {"id": "f0acab04-6eb6-4d43-af38-78b29b855c1b", "type": "concept", "title": "Untranslatable terms"}, {"id": "266054d4-c2d8-4ea7-943d-1481849dbbd0", "type": "concept", "title": "Ethnographic translation"}, {"id": "78ec7a33-2393-4e61-9f3b-33655b5df1a7", "type": "concept", "title": "Language endangerment and revitalization"}], "description": "Students learn why translation is cultural interpretation, not word substitution."}]}, {"id": "c28f7a52-cf47-4cf8-ba17-1e96d01e0083", "type": "topic", "title": "Globalization, Migration, Diaspora, Development, and Transnationalism", "description": "Culture is not bounded by place. Students study how migration, diaspora, media, capital, aid, tourism, and global institutions create transnational social fields.", "children": [{"id": "713321cf-faba-4e31-a581-eb93a41f4f29", "type": "subtopic", "title": "Globalization and Cultural Flows", "children": [{"id": "973cacde-961b-4a09-a01c-4a504df5683a", "type": "concept", "title": "Cultural flows and hybridity"}, {"id": "2fd89572-b402-4508-8607-d426685951b7", "type": "concept", "title": "Global capitalism"}, {"id": "e4fbb112-ee7f-4c96-a5e3-c51a6b0c0a01", "type": "concept", "title": "Media and consumption"}, {"id": "6a510a1f-7da2-4030-af23-6a7ebb7ea0c5", "type": "concept", "title": "Local responses to global forms"}], "description": "Students learn how goods, people, images, ideas, and institutions move unevenly."}, {"id": "41291c33-0572-4d35-a963-a7d36facf424", "type": "subtopic", "title": "Migration and Diaspora", "children": [{"id": "08df712b-9f88-4ffb-abbc-5c6c5d3ea70b", "type": "concept", "title": "Refugees and displacement"}, {"id": "54c3327f-20a5-48e0-ac72-831d953e36bd", "type": "concept", "title": "Labor migration"}, {"id": "43a23ae8-4a8c-45c0-b30d-800454880174", "type": "concept", "title": "Transnational families"}, {"id": "ce69fd67-ca1f-4cd1-ab92-a80456adfae9", "type": "concept", "title": "Diaspora, home, and belonging"}], "description": "The point is to analyze movement as social, economic, political, and emotional."}, {"id": "fa0d2a86-725a-4465-a8cc-b6f736bfe6f7", "type": "subtopic", "title": "Development and Aid", "children": [{"id": "da0c64ef-dd06-40a9-b414-17022e766221", "type": "concept", "title": "Development discourse"}, {"id": "fab6daf1-1d37-419e-882e-013d79fda097", "type": "concept", "title": "NGOs and humanitarianism"}, {"id": "f27a4014-0058-4cf4-bd5e-7946070873f6", "type": "concept", "title": "Participation and community work"}, {"id": "d30d5afc-ec64-4a04-8256-4cbc1ea4b36c", "type": "concept", "title": "Critiques of aid and intervention"}], "description": "Students examine development as an arena of power, expertise, hope, and unintended consequences."}]}, {"id": "2bfa4420-c532-4ea1-9a67-de13cd5d0e77", "type": "topic", "title": "Health, Illness, Medicine, Healing, and Structural Violence", "description": "Medical anthropology connects bodies, illness, care, institutions, and inequality. Students learn that health is biological, cultural, political, and economic at once.", "children": [{"id": "46b392c2-5414-4003-a84d-ce0d65c4f4a1", "type": "subtopic", "title": "Illness Experience and Healing", "children": [{"id": "775b5ccb-ab01-47ed-899a-8ce4bbc8283f", "type": "concept", "title": "Illness narratives"}, {"id": "486bddde-dabf-4122-b888-f0add58db9a7", "type": "concept", "title": "Biomedicine as culture"}, {"id": "1c456c9c-523d-424b-9ef2-fc6eb266723b", "type": "concept", "title": "Therapeutic pluralism"}, {"id": "b190e94c-2848-4a0b-b442-9ba45e0357e5", "type": "concept", "title": "Healing, ritual, and care"}], "description": "Students learn how people interpret suffering and seek care across medical systems."}, {"id": "2686bf80-f19d-4908-9e52-bc2875128ebf", "type": "subtopic", "title": "Structural Violence and Health Inequality", "children": [{"id": "b37cd60e-f967-4e24-ae89-fcce2edc3e1c", "type": "concept", "title": "Poverty and health"}, {"id": "4a13b389-eb90-4ede-bc8c-b2cf0c46957f", "type": "concept", "title": "Racism and health"}, {"id": "3c6d6fad-0522-4f58-8de8-05470112955a", "type": "concept", "title": "Migration and labor injury"}, {"id": "c1aa91d6-b803-4c41-bf44-bd936829d451", "type": "concept", "title": "Environmental illness"}], "description": "The gist is understanding how social arrangements become embodied as disease and premature death."}, {"id": "3c61b6ba-d920-49c1-ad17-e30bcab20a90", "type": "subtopic", "title": "Global Health and Epidemics", "children": [{"id": "2eb55ef3-22cc-48a3-854c-422f2871cccf", "type": "concept", "title": "Epidemics and social trust"}, {"id": "79cafa28-c8f8-4038-a912-ad9855376582", "type": "concept", "title": "Public health infrastructure"}, {"id": "028df5b3-c190-4d98-a1a4-fdc061c60674", "type": "concept", "title": "Humanitarian medicine"}, {"id": "8d59909f-113b-471f-b108-740a55ef6ba9", "type": "concept", "title": "Ethics of intervention"}], "description": "Students learn to analyze global health institutions, expertise, and crisis response."}]}, {"id": "aad4d67c-a8f5-435c-99ae-cd1838480f01", "type": "topic", "title": "Material Culture, Environment, Media, Technology, and Digital Life", "description": "Material things, environments, infrastructures, and media mediate social life. Students learn how culture is made through objects, technologies, landscapes, and nonhuman relations.", "children": [{"id": "dedc9629-4698-4a1d-9295-e1be891b77cf", "type": "subtopic", "title": "Material Culture and Objects", "children": [{"id": "c540f45e-73a6-498b-8c2e-0e8b4c3617da", "type": "concept", "title": "Things, gifts, commodities, and heirlooms"}, {"id": "a6f18e96-0483-40fd-888b-d04cf7ee9356", "type": "concept", "title": "Museums and collecting"}, {"id": "2ab3dd5e-7a0a-40ac-812b-f0cb7cba35b7", "type": "concept", "title": "Heritage and repatriation"}, {"id": "9630b31d-ed6e-42db-8557-3b6535a3aa1f", "type": "concept", "title": "Everyday objects and memory"}], "description": "Students learn to read objects as social evidence."}, {"id": "261677c1-89ca-4d44-b752-95889a69ec03", "type": "subtopic", "title": "Environment and Multispecies Worlds", "children": [{"id": "44fc8feb-a524-407b-b795-4fb04836af47", "type": "concept", "title": "Political ecology"}, {"id": "3eda4c21-5126-4fa2-9b1f-d77a6c6b897e", "type": "concept", "title": "Climate and vulnerability"}, {"id": "c669b6f0-2d60-4b89-914b-94477ab56eb5", "type": "concept", "title": "Food systems"}, {"id": "01516cfb-f84e-4612-8852-4f1a587e9b78", "type": "concept", "title": "Animals, plants, microbes, and care"}], "description": "The point is to understand humans as ecological and multispecies beings."}, {"id": "8fa12142-6cb0-42f7-b09a-0aa533c6576e", "type": "subtopic", "title": "Media, Technology, and Digital Life", "children": [{"id": "c57ce5d4-b460-487e-b299-ebe6243fbf85", "type": "concept", "title": "Digital ethnography"}, {"id": "80fcbf56-2f4d-40f3-a8e5-51c1ea59850b", "type": "concept", "title": "Platforms and algorithms"}, {"id": "add7a452-817c-4c91-b47b-3869f40102d2", "type": "concept", "title": "Media circulation"}, {"id": "07609399-b1f5-49fa-85ee-0e86f443f0f9", "type": "concept", "title": "Infrastructure and inequality"}], "description": "Students examine digital and mediated social worlds ethnographically."}]}, {"id": "78086dda-70ef-416a-9e0a-20a7d59c51b3", "type": "topic", "title": "Anthropological Theory: Boas, Functionalism, Structuralism, Practice, Feminist and Postcolonial Critiques", "description": "Theory helps students name what they see in ethnographic cases. This unit maps major anthropological schools and the debates that shape contemporary cultural anthropology.", "children": [{"id": "19035d50-276c-4242-b1f1-aa98fc8a2a5b", "type": "subtopic", "title": "Foundational Theory Traditions", "children": [{"id": "a8ee13ca-d92e-40cb-b800-a0fede78578f", "type": "concept", "title": "Evolutionism and critique"}, {"id": "fb1577d7-2898-43fb-9440-5c1c0796e26c", "type": "concept", "title": "Boas and historical particularism"}, {"id": "f9a25d5f-a9ad-489a-8a45-0373392e9120", "type": "concept", "title": "Functionalism and structural functionalism"}, {"id": "63dee1af-dc15-452f-948b-3edada698a99", "type": "concept", "title": "Structuralism and symbolic anthropology"}], "description": "Students learn how anthropology moved from evolutionism to historical particularism, functionalism, and structuralism."}, {"id": "0b8b10dc-8171-456b-b064-bd3bee897fda", "type": "subtopic", "title": "Practice, Political Economy, and Interpretation", "children": [{"id": "0f38b8ca-06f7-4ccd-ab40-c3988e6afcca", "type": "concept", "title": "Geertz and thick description"}, {"id": "d9f2794b-3378-41c7-86d1-48b0dca1b696", "type": "concept", "title": "Bourdieu and practice"}, {"id": "2f47692d-54f2-4cd3-a7a9-304794128651", "type": "concept", "title": "Marxist and political economy approaches"}, {"id": "6caf8fb8-7739-4a07-b9ae-ea48c6f0c8b7", "type": "concept", "title": "Agency, structure, and habitus"}], "description": "The gist is learning how theory connects meaning, agency, power, and material life."}, {"id": "2f14ae96-18f2-49e3-bad5-08e1044677d8", "type": "subtopic", "title": "Contemporary Critiques and Turns", "children": [{"id": "d1147e62-0123-4ebc-a0bd-dd6f182c7d82", "type": "concept", "title": "Feminist anthropology"}, {"id": "3f38ac8f-6330-4711-86f1-9caff6050d0d", "type": "concept", "title": "Postcolonial and decolonial critiques"}, {"id": "f1f225ec-02ef-45f0-aac4-d4a9aebfd3ed", "type": "concept", "title": "Science, technology, and materiality"}, {"id": "2cfa0916-7f58-44e2-8dc8-36c3772f1888", "type": "concept", "title": "Ontological and multispecies turns"}], "description": "Students learn how feminist, postcolonial, Indigenous, science studies, and multispecies work transformed the field."}]}, {"id": "e593ba70-ffec-4f1f-810e-98314b992c08", "type": "topic", "title": "Applied and Public Anthropology: Design, Policy, Advocacy, and Ethnographic Writing", "description": "The final unit asks students to use anthropological insight publicly and responsibly. They learn to write ethnographically, translate findings, and imagine anthropology beyond the classroom.", "children": [{"id": "75741a1a-ed67-4e28-a28f-024cd7ed1ce6", "type": "subtopic", "title": "Applied and Public Anthropology", "children": [{"id": "a6f1f0c3-70ff-469b-8211-40fd47a129d4", "type": "concept", "title": "Applied anthropology"}, {"id": "322cd33d-2553-43e8-ae23-bbf9fed7d847", "type": "concept", "title": "Public anthropology"}, {"id": "25d7649e-16f1-4c84-a90c-476f30a64e26", "type": "concept", "title": "Engaged and collaborative research"}, {"id": "c8b00ecc-f074-4fb0-8974-979cee5b181e", "type": "concept", "title": "Needs assessment and program evaluation"}], "description": "Students learn how anthropologists work in policy, health, design, museums, education, development, environment, and advocacy."}, {"id": "5e73b9ce-2ff7-4199-bdae-e37727c82acf", "type": "subtopic", "title": "Design, Policy, and Professional Practice", "children": [{"id": "c7a8893b-dc24-4efb-bdb0-084749e73a10", "type": "concept", "title": "Design anthropology and UX research"}, {"id": "3567d4f9-3e26-4129-8604-f023df8f23ad", "type": "concept", "title": "Policy translation"}, {"id": "9e740583-fbfd-4b8f-aa9f-f6bd291464ed", "type": "concept", "title": "Stakeholder analysis"}, {"id": "ced13291-10a1-45e5-b561-634b40bda845", "type": "concept", "title": "Ethics of intervention"}], "description": "The point is to connect ethnographic methods to real-world decision-making without flattening cultural complexity."}, {"id": "98595eb9-d98d-4527-b598-cbac7bcdb4c7", "type": "subtopic", "title": "Ethnographic Writing and Presentation", "children": [{"id": "05e46159-09df-4df4-8d0e-2f8d9a9ef273", "type": "concept", "title": "Ethnographic vignette"}, {"id": "34a9fff1-34ed-44f4-b865-dc78118867e3", "type": "concept", "title": "Thick description and argument"}, {"id": "7bd02085-cee1-411d-9886-dec379ea4ed4", "type": "concept", "title": "Audience and voice"}, {"id": "63e78aef-c8cc-4dd7-a2fd-5c77a41b0253", "type": "concept", "title": "Final portfolio or public-facing brief"}], "description": "Students synthesize the course by writing, revising, and presenting anthropological analysis."}]}], "dbBacked": true}$cuanjson$::jsonb,
